<?php declare(strict_types=1);$base=config('app.base_path');$isTrash=!empty($trash);?><div class="page-header"><div><h1><?= $isTrash?'Deleted Item Variants':'Item Variants' ?></h1><p><?= $isTrash?'Restore variants from Trash.':'Alternative sizes or configurations for menu items.' ?></p></div><div class="page-actions"><?php if($isTrash): ?><a class="btn btn-secondary" href="<?= $base ?>/restaurant/variants">Active Variants</a><?php else: ?><a class="btn btn-secondary" href="<?= $base ?>/restaurant/variants?view=trash">Trash</a><a class="btn btn-primary" href="<?= $base ?>/restaurant/variants/create">Add Variant</a><?php endif; ?></div></div><div class="card"><table class="table"><thead><tr><th>Restaurant</th><th>Item</th><th>Variant</th><th>Price</th><th>Available</th><th>Actions</th></tr></thead><tbody><?php if(empty($variants)): ?><tr><td colspan="6"><div class="empty-state"><?= $isTrash?'Trash is empty.':'No variants found.' ?></div></td></tr><?php else:foreach($variants as $v):?><tr><td><?=htmlspecialchars((string)$v['restaurant_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars((string)$v['item_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars((string)$v['name'],ENT_QUOTES,'UTF-8')?></td><td>₹<?=number_format((float)$v['price'],2)?></td><td><?=!empty($v['is_available'])?'Yes':'No'?></td><td><?php if($isTrash): ?><form method="post" action="<?=$base?>/restaurant/variants/<?= (int)$v['id']?>/restore"><button class="btn btn-secondary" type="submit">Restore</button></form><?php else: ?><a class="link-button" href="<?=$base?>/restaurant/variants/<?= (int)$v['id']?>/edit">Edit</a><?php endif; ?></td></tr><?php endforeach;endif;?></tbody></table></div>
